/**
 * Guardas determinísticas, aplicadas antes de qualquer chamada ao LLM.
 *
 * JavaScript puro, sem require: o scripts/build.js copia este ficheiro
 * (até à linha de corte) para os Code nodes. Todas as funções recebem
 * a configuração como argumento, para se poderem testar sem o n8n.
 *
 * Duas famílias:
 *  - tráfego (sub-workflow guard-trafego, chamado pelos adaptadores públicos);
 *  - conteúdo e custo (chat-core, corre em todos os canais, incluindo o eval).
 */

/** Motivos de bloqueio. São também os valores gravados em turns.guarda. */
const MOTIVOS_BLOQUEIO = [
  'sessao_invalida',
  'sessao_bloqueada',
  'mensagem_vazia',
  'mensagem_longa',
  'quarentena',
  'limite_sessao',
  'teto_global',
  'kill_switch_custo',
  'pedido_invalido', // não é uma mensagem de texto (ex.: ficheiros enviados diretamente ao webhook)
  'sem_kb', // não há base de conhecimento ativa: o agente não responde sem ela
];

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

/** Limpa o texto recebido: NFC, sem caracteres de controlo, espaços arrumados. */
function normalizarTexto(texto) {
  if (texto === null || texto === undefined) return '';
  return String(texto)
    .normalize('NFC')
    .replace(/\r\n?/g, '\n')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F​-‏‪-‮⁠-⁤﻿]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/** Minúsculas e sem acentos, para as regras não dependerem da grafia. */
function paraComparar(texto) {
  return String(texto)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function validarSessionId(id) {
  return typeof id === 'string' && UUID_RE.test(id);
}

/*
 * Regras de quarentena. Cada regra tem um id (fica registado no turno) e
 * corre sobre o texto sem acentos e em minúsculas, exceto as marcadas com
 * `original: true`.
 *
 * Critério: apanhar pedidos dirigidos ao bot (as instruções dele, os
 * segredos dele, mudar o papel dele), não temas. Um visitante pode
 * perguntar como guardamos as credenciais dos clientes; isso não é ataque.
 */
const REGRAS_INJECAO = [
  {
    id: 'ignorar_instrucoes',
    // "Regras" sozinho não chega ("posso ignorar as regras do IVA?"): só
    // conta com um qualificador que aponte para as instruções do bot.
    re: /\b(ignor[ae]\w*|esquec[ea]\w*|desconsider[ae]\w*|ignore|disregard|forget)\b.{0,40}(\b(instruc\w*|instructions?|prompts?)\b|\b(regras|ordens|indicac\w*|rules)\b.{0,20}\b(anteriores|acima|iniciais|previous|above|prior|que (te|lhe) deram)\b|\b(tudo|everything)\b.{0,15}\b(acima|anterior|above|before)\b)/,
  },
  {
    id: 'pedir_prompt',
    re: /\b(system ?prompt|prompt (do|de) sistema|prompt inicial|initial prompt|(instrucoes|regras|orientacoes) (do sistema|iniciais|internas|originais|secretas|que (te|lhe) (deram|foram dadas)|que recebeste)|your (instructions|rules|system message)|developer message)\b/,
  },
  {
    id: 'repetir_contexto',
    re: /\b(repete|repita|reescreve|reescreva|copia|copie|imprime|imprima|mostra|mostre|repeat|print|output|show)\b.{0,30}\b(tudo|todo o texto|o texto|everything|all|the text|the words)\b.{0,20}\b(acima|anterior|antes disto|above|before this)\b/,
  },
  {
    // Só segredos *do bot* (possessivo antes ou depois): "a tua API key",
    // "a password do vosso n8n". "Credenciais dos nossos clientes" passa.
    id: 'pedir_segredos',
    re: (() => {
      const dono = '(tua|teu|tuas|teus|vossa|vosso|vossas|vossos|your|do bot|do servidor|do n8n|da openai|do openrouter)';
      const segredo =
        '(api[ _-]?keys?|chaves? (da|de) api|chaves? secretas?|tokens?|passwords?|palavras?[- ]passe|senhas?|credenciais|credentials|secrets?|variaveis de ambiente|environment variables|\\.env)';
      return new RegExp(`\\b${dono}\\b\\W+(\\w+\\W+){0,3}${segredo}\\b|\\b${segredo}\\W+(\\w+\\W+){0,3}${dono}\\b`);
    })(),
  },
  {
    id: 'mudar_papel',
    re: /\b(a partir de agora (es|seras|vais ser|passas a ser|ages)|finge (que es|ser)|faz de conta que es|comporta-te como|you are now|from now on you|act as|pretend (to be|you are)|roleplay|jailbreak|modo (dev|desenvolvedor|developer|sem restricoes)|developer mode|do anything now)\b/,
  },
  {
    id: 'marcadores_sistema',
    original: true,
    re: /(<\|?\s*(system|im_start|im_end|endoftext)\s*\|?>|\[\/?(system|inst)\]|<\/?system>|^\s*#{1,6}\s*(system|instructions?)\s*:?\s*$)/im,
  },
  {
    // Base64 ou semelhante: um bloco longo sem espaços que mistura
    // maiúsculas, minúsculas e dígitos (texto repetido não conta).
    id: 'bloco_codificado',
    original: true,
    testa: (t) =>
      (t.match(/[A-Za-z0-9+/]{120,}={0,2}/g) || []).some((b) => /[A-Z]/.test(b) && /[a-z]/.test(b) && /\d/.test(b)),
  },
];

/** Devolve as regras de quarentena que o texto aciona (lista vazia = limpo). */
function detetarInjecao(texto) {
  const original = String(texto || '');
  const comparavel = paraComparar(original);
  return REGRAS_INJECAO.filter((r) => {
    const alvo = r.original ? original : comparavel;
    return r.testa ? r.testa(alvo) : r.re.test(alvo);
  }).map((r) => r.id);
}

/**
 * Guardas de conteúdo (chat-core). Corre em todos os canais.
 * `estado.quarentenasRecentes`: quarentenas da sessão na janela de bloqueio.
 */
function avaliarConteudo(payload, cfg, estado) {
  const quarentenas = (estado && estado.quarentenasRecentes) || 0;
  const texto = normalizarTexto(payload && payload.texto);
  const bloqueio = (motivo, regras) => ({ permitido: false, motivo, regras: regras || [], texto });

  if (!validarSessionId(payload && payload.session_id)) return bloqueio('sessao_invalida');
  if (quarentenas >= cfg.limites.quarentenasMaxPorSessao) return bloqueio('sessao_bloqueada');
  if (!texto) return bloqueio('mensagem_vazia');
  if (texto.length > cfg.limites.mensagemMaxChars) return bloqueio('mensagem_longa');

  const regras = detetarInjecao(texto);
  if (regras.length) return bloqueio('quarentena', regras);

  return { permitido: true, motivo: null, regras: [], texto };
}

/**
 * Guardas de tráfego (guard-trafego). As contagens já incluem o pedido
 * atual, porque o contador é incrementado antes de se avaliar.
 * O teto global vem primeiro: é a proteção real, porque o session_id é
 * gerado no cliente e pode ser rodado.
 */
function avaliarTrafego(contagens, cfg) {
  const l = cfg.limites;
  const c = contagens || {};
  if ((c.globalMin || 0) > l.globalPorMinuto || (c.globalDia || 0) > l.globalPorDia) {
    return { permitido: false, motivo: 'teto_global' };
  }
  if ((c.sessaoMin || 0) > l.sessaoPorMinuto || (c.sessaoDia || 0) > l.sessaoPorDia) {
    return { permitido: false, motivo: 'limite_sessao' };
  }
  return { permitido: true, motivo: null };
}

/** Teto diário do canal; sem teto configurado é 0 (canal fechado). */
function tetoCustoDiario(canal, cfg) {
  return Number(cfg.limites.custoDiarioMaxEur[canal]) || 0;
}

/** Kill switch: bloqueia quando o custo estimado do dia no canal chega ao teto. */
function avaliarCusto(custoHojeEur, canal, cfg) {
  if (Number(custoHojeEur || 0) >= tetoCustoDiario(canal, cfg)) {
    return { permitido: false, motivo: 'kill_switch_custo' };
  }
  return { permitido: true, motivo: null };
}

/*
 * Estimativa de tokens. O AI Agent do n8n não passa o consumo real aos
 * nós seguintes, por isso o custo registado é estimado (~4 caracteres por
 * token). O valor real fica no painel do OpenRouter.
 */
function estimarTokens(texto) {
  return Math.ceil(String(texto || '').length / 4);
}

/**
 * Consumo estimado de um turno do agente. Cada chamada a uma tool é mais
 * uma ida ao modelo, que volta a receber o contexto inteiro (sistema + KB +
 * histórico + mensagem) e os passos anteriores.
 * `c`: { sistemaChars, historicoChars, textoChars, respostaChars,
 *        passos: [{ entrada, saida }] }  (entrada/saida das tools, em texto)
 */
function estimarConsumo(c, cfg) {
  const passos = c.passos || [];
  const base = (c.sistemaChars || 0) + (c.historicoChars || 0) + (c.textoChars || 0);
  const iteracoes = 1 + passos.length;
  let acumulado = 0;
  let entradaChars = 0;
  let saidaChars = c.respostaChars || 0;
  for (let i = 0; i < iteracoes; i++) {
    entradaChars += base + acumulado;
    if (i < passos.length) {
      const e = String(passos[i].entrada || '').length;
      const s = String(passos[i].saida || '').length;
      saidaChars += e;
      acumulado += e + s;
    }
  }
  const tokensEntrada = Math.ceil(entradaChars / 4);
  const tokensSaida = Math.ceil(saidaChars / 4);
  return { tokensEntrada, tokensSaida, custoEur: estimarCustoEur(tokensEntrada, tokensSaida, cfg) };
}

function estimarCustoEur(tokensEntrada, tokensSaida, cfg) {
  const m = cfg.modelo;
  const usd = (tokensEntrada * m.precoEntradaUsdPorMilhao + tokensSaida * m.precoSaidaUsdPorMilhao) / 1e6;
  return Math.round(usd * cfg.usdParaEur * 1e6) / 1e6;
}

/** Resposta fixa e útil para cada bloqueio. Nunca chama o LLM. */
function respostaFixa(motivo, cfg) {
  const cal = `[${cfg.cal.textoLink}](${cfg.cal.url})`;
  const email = cfg.site.emailContacto;
  const textos = {
    sessao_invalida: 'Não consegui ler esta conversa. Recarregue a página e tente outra vez.',
    sessao_bloqueada: `Esta conversa foi pausada. Se quiser falar connosco, pode ${cal} ou escrever para ${email}.`,
    mensagem_vazia: 'Não recebi nenhuma mensagem. Em que posso ajudar?',
    mensagem_longa: `A mensagem é um pouco longa para este chat. Consegue resumi-la em poucas frases? Se preferir explicar com calma, pode ${cal}.`,
    quarentena: `Não posso ajudar com esse pedido. Posso responder a perguntas sobre os serviços da Náutica AI ou ajudar a ${cal}.`,
    limite_sessao: `Está a enviar mensagens muito depressa. Aguarde um minuto e tente outra vez. Se preferir, pode ${cal}.`,
    teto_global: `De momento o assistente não está disponível. Pode ${cal} ou escrever para ${email}.`,
    kill_switch_custo: `De momento o assistente não está disponível. Pode ${cal} ou escrever para ${email}.`,
    pedido_invalido: `Este chat só aceita mensagens de texto. Se precisar de nos enviar um ficheiro, escreva para ${email}.`,
    sem_kb: `Desculpe, não consigo responder agora. Pode ${cal} ou escrever para ${email} e a nossa equipa responde-lhe.`,
    fallback: `Desculpe, não consegui responder agora. Pode ${cal} ou escrever para ${email} e a nossa equipa responde-lhe.`,
  };
  return textos[motivo] || textos.fallback;
}

// ===== src/posprocessar.js =====
/**
 * Pós-processamento da resposta do agente, antes de chegar ao visitante.
 *
 * Ordem: links fora da allowlist → links do Cal.com passam a marcador →
 * corte por tamanho → chamada à ação (marcador trocado pelo link do
 * Cal.com) → URLs soltos passam a clicáveis → deteção de português do Brasil.
 * O corte vem antes do link do Cal.com para o URL não contar para o
 * tamanho visível nem ser cortado a meio.
 *
 * JavaScript puro, sem require, copiado para os Code nodes pelo build.
 */

/**
 * Partes de um URL http(s). Os Code nodes do n8n correm num ambiente
 * isolado sem o objeto global URL, por isso a leitura é feita aqui.
 * Devolve null se não for um URL http(s) válido.
 */
function partirUrl(url) {
  const m = /^(https?):\/\/(?:([^@/?#]*)@)?([^/:?#]+)(?::(\d*))?([^?#]*)(\?[^#]*)?(#.*)?$/i.exec(String(url).trim());
  if (!m) return null;
  return {
    protocolo: m[1].toLowerCase(),
    credenciais: m[2] || '',
    host: m[3].toLowerCase(),
    porta: m[4] || '',
    caminho: m[5] || '/',
    query: m[6] || '',
  };
}

/** O URL pode aparecer numa resposta? Só https, sem credenciais nem porta. */
function linkPermitido(url, cfg) {
  if (/^mailto:/i.test(url)) {
    return url.slice(7).split('?')[0].toLowerCase() === cfg.site.emailContacto.toLowerCase();
  }
  const u = partirUrl(url);
  if (!u || u.protocolo !== 'https' || u.credenciais || u.porta) return false;
  const caminho = u.caminho.endsWith('/') ? u.caminho : u.caminho + '/';
  return cfg.linksPermitidos.some((p) => u.host === p.host && caminho.startsWith(p.prefixo));
}

/**
 * Remove links fora da allowlist. Num link Markdown fica só o texto; um
 * URL solto desaparece. Devolve também os URLs removidos, para o log.
 */
function filtrarLinks(texto, cfg) {
  const removidos = [];
  const guardados = [];
  const marca = (i) => `\u0000${i}\u0000`;

  // 1. Links Markdown: [texto](url)
  let t = String(texto).replace(/\[([^\]\n]*)\]\(\s*<?([^)\s>]+)>?\s*\)/g, (m, txt, url) => {
    if (linkPermitido(url, cfg)) {
      guardados.push(m);
      return marca(guardados.length - 1);
    }
    removidos.push(url);
    return txt;
  });

  // 2. URLs soltos (com esquema, www. ou mailto:)
  t = t.replace(/\b(?:https?:\/\/|www\.)[^\s<>()[\]]+|\bmailto:[^\s<>()[\]]+/gi, (m) => {
    const final = (m.match(/[.,;:!?'"»]+$/) || [''])[0];
    const url = m.slice(0, m.length - final.length);
    const comEsquema = /^www\./i.test(url) ? 'https://' + url : url;
    if (linkPermitido(comEsquema, cfg)) return m;
    removidos.push(url);
    return final;
  });

  t = t.replace(/\u0000(\d+)\u0000/g, (m, i) => guardados[Number(i)]);
  t = t.replace(/[ \t]{2,}/g, ' ').replace(/ +([.,;:!?])/g, '$1');
  return { texto: t.trim(), removidos };
}

/**
 * Corta acima do limite, de preferência no fim de uma frase. Nunca deixa
 * um link Markdown ou um marcador a meio.
 */
function cortarResposta(texto, max) {
  const t = String(texto);
  if (t.length <= max) return { texto: t, cortada: false };

  let corte = t.slice(0, max);
  const abre = corte.lastIndexOf('[');
  if (abre > corte.lastIndexOf(')')) corte = corte.slice(0, abre);

  const fimFrase = Math.max(
    corte.lastIndexOf('. '),
    corte.lastIndexOf('! '),
    corte.lastIndexOf('? '),
    corte.lastIndexOf('.\n'),
    corte.lastIndexOf('!\n'),
    corte.lastIndexOf('?\n')
  );
  if (fimFrase >= max * 0.5) return { texto: corte.slice(0, fimFrase + 1).trim(), cortada: true };

  const espaco = corte.search(/\s\S*$/);
  if (espaco > 0) corte = corte.slice(0, espaco);
  return { texto: corte.replace(/[\s,;:–-]+$/, '') + '…', cortada: true };
}

/** URL do Cal.com com nome e email pré-preenchidos (só os que existem). */
function urlCal(nome, email, cfg) {
  const params = [];
  if (nome) params.push('name=' + encodeURIComponent(nome));
  if (email) params.push('email=' + encodeURIComponent(email));
  return cfg.cal.url + (params.length ? '?' + params.join('&') : '');
}

/** Conta do Cal.com no URL configurado ("nautica-ai-xuismz"). */
function contaCal(cfg) {
  const u = partirUrl(cfg.cal.url);
  return u ? u.caminho.split('/')[1] : '';
}

/**
 * Troca o primeiro marcador pelo link do Cal.com, se a conversa ainda não
 * esgotou as chamadas à ação. Os restantes marcadores são removidos.
 * Um link do Cal.com escrito diretamente pelo agente também conta.
 */
/**
 * Marcador da CTA, com texto opcional: "[[MARCAR]]" (texto por omissão,
 * cal.textoLink) ou "[[MARCAR|texto]]", que o calParaMarcador cria quando o
 * agente escreveu o seu próprio link do Cal.com, para a frase dele continuar
 * a fazer sentido ("pode [marcar um horário](…)").
 */
function regexMarcador(cfg) {
  const base = cfg.marcadorCta.slice(0, -2).replace(/[[\]|]/g, '\\$&');
  return new RegExp(base + '(?:\\|([^\\]\\n]{1,80}))?\\]\\]', 'g');
}

function aplicarCta(texto, ctx, cfg) {
  const anteriores = (ctx && ctx.ctasAnteriores) || 0;
  const podeUsar = anteriores < cfg.limites.ctasMaxPorConversa;
  let usada = false;

  let t = String(texto).replace(regexMarcador(cfg), (m, rotulo) => {
    if (!podeUsar || usada) return '';
    usada = true;
    const url = urlCal(ctx && ctx.nome, ctx && ctx.email, cfg);
    return `[${(rotulo || '').trim() || cfg.cal.textoLink}](${url})`;
  });

  // Arruma o que sobra de marcadores removidos (bullets vazios, espaços).
  t = t
    .replace(/^[ \t]*[-*•][ \t]*$/gm, '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/ +([.,;:!?])/g, '$1')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  if (!usada) usada = t.includes('cal.com/' + contaCal(cfg) + '/');
  return { texto: t, ctaUsada: usada };
}

/**
 * Links do Cal.com escritos pelo agente (a base tem o URL por extenso)
 * passam a marcador: assim levam nome e email pré-preenchidos, contam para
 * o máximo de chamadas à ação e são removidos se esse máximo já foi usado.
 */
function calParaMarcador(texto, cfg) {
  const conta = contaCal(cfg).replace(/[^a-z0-9-]/gi, '');
  const url = 'https?://(?:app\\.)?cal\\.com/' + conta + '(?:/[^\\s)\\]]*)?';
  return String(texto)
    .replace(new RegExp('\\[([^\\]\\n|]*)\\]\\(\\s*<?' + url + '>?\\s*\\)', 'g'), (m, rotulo) => {
      const r = rotulo.trim();
      return r ? cfg.marcadorCta.slice(0, -2) + '|' + r + ']]' : cfg.marcadorCta;
    })
    .replace(new RegExp('(?<![\\w/])' + url, 'g'), (m) => {
      const final = (m.match(/[.,;:!?'"»]+$/) || [''])[0];
      return cfg.marcadorCta + final;
    });
}

/**
 * URLs soltos (já filtrados pela allowlist) passam a links Markdown: o
 * widget não torna URLs soltos clicáveis.
 */
function tornarClicaveis(texto) {
  const guardados = [];
  let t = String(texto).replace(/\[[^\]\n]*\]\([^)\s]+\)/g, (m) => {
    guardados.push(m);
    return '\u0000' + (guardados.length - 1) + '\u0000';
  });
  t = t.replace(/\b(?:https:\/\/|www\.)[^\s<>()[\]\u0000]+/gi, (m) => {
    const final = (m.match(/[.,;:!?'"»]+$/) || [''])[0];
    const url = m.slice(0, m.length - final.length);
    const href = /^www\./i.test(url) ? 'https://' + url : url;
    const rotulo = href.replace(/^https:\/\/(www\.)?/i, '').replace(/\/$/, '');
    return '[' + rotulo + '](' + href + ')' + final;
  });
  return t.replace(/\u0000(\d+)\u0000/g, (m, i) => guardados[Number(i)]);
}

const MARCADORES_PT_BR = [
  { id: 'gerundio', re: /\b(estou|esta|estamos|estao|estava|estavamos|fico|ficamos|continuo|continua|seguimos|vou ficar)\s+\w+(ando|endo|indo)\b/ },
  { id: 'voce', re: /\bvoce\b/ },
  { id: 'lexico', re: /\b(contato|contatos|contatar|celular|planilhas?|equipe|usuarios?|cadastr\w*|registrar|registrou|aplicativo|onibus|de fato|bacana|pra|xicara)\b/ },
  { id: 'acentuacao', original: true, re: /[a-zà-ú]*(ômic|ônic|ônim|ônio|êmic|ênic|ênio)[a-zà-ú]*/i },
];

/** Sinal (não bloqueia) de deriva para português do Brasil. */
function detetarPtBr(texto) {
  const original = String(texto || '');
  const comparavel = original.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const marcadores = MARCADORES_PT_BR.filter((m) => m.re.test(m.original ? original : comparavel)).map((m) => m.id);
  return { suspeito: marcadores.length > 0, marcadores };
}

/**
 * Pipeline completo. `ctx`: { nome, email, ctasAnteriores } da sessão.
 */
/**
 * A marca escreve-se "Náutica". O título "Sobre a Nautica" da base e os
 * domínios não levam acento, e o modelo copia-os. Só toca na palavra com
 * maiúscula e solta, por isso os URLs (em minúsculas) ficam intactos.
 */
function grafiaMarca(texto) {
  return String(texto || '').replace(/(?<![\w./@-])Nautica(?![\w-])/g, 'Náutica');
}

function posProcessar(texto, ctx, cfg) {
  const links = filtrarLinks(grafiaMarca(texto), cfg);
  const comMarcador = calParaMarcador(links.texto, cfg);
  const corte = cortarResposta(comMarcador, cfg.limites.respostaMaxChars);
  const cta = aplicarCta(corte.texto, ctx, cfg);
  const final = tornarClicaveis(cta.texto);
  const ptBr = detetarPtBr(final);
  return {
    texto: final,
    vazia: !final,
    linksRemovidos: links.removidos,
    cortada: corte.cortada,
    ctaUsada: cta.ctaUsada,
    ptBr,
  };
}

// ===== src/contexto.js =====
/**
 * Contexto do agente e leitura do que ele fez.
 *
 * A mensagem de sistema é: prompt (do repositório) + base de conhecimento
 * (versão ativa) + estado da conversa. As duas primeiras partes não mudam
 * entre turnos, por isso ficam no início: é esse prefixo estável que a
 * cache de prompt dos fornecedores aproveita. O estado, que muda, vai no fim.
 *
 * JavaScript puro, sem require, copiado para os Code nodes pelo build.
 */

function montarMensagemSistema(prompt, kbConteudo, estado, cfg) {
  const e = estado || {};
  const linhas = [
    `- Chamadas à ação já usadas nesta conversa: ${e.ctasAnteriores || 0} de ${cfg.limites.ctasMaxPorConversa}.`,
    `- Nome do visitante já registado: ${e.nome ? 'sim (' + e.nome + ')' : 'não'}.`,
    `- Email ou telefone já registado: ${e.temContacto ? 'sim' : 'não'}.`,
  ];
  return [
    String(prompt).trim(),
    '# Base de conhecimento\n\n' + String(kbConteudo).trim(),
    '# Estado desta conversa\n\n' + linhas.join('\n'),
  ].join('\n\n---\n\n');
}

function textoDe(valor) {
  if (valor === null || valor === undefined) return '';
  return typeof valor === 'string' ? valor : JSON.stringify(valor);
}

/**
 * Resume os intermediateSteps do AI Agent: nomes das tools (para o log,
 * sem os argumentos, que têm dados pessoais) e tamanhos (para o custo).
 */
function resumirPassos(passos) {
  const lista = Array.isArray(passos) ? passos : [];
  return {
    tools: lista.map((p) => (p && p.action && p.action.tool) || 'desconhecida'),
    passos: lista.map((p) => ({
      entrada: textoDe(p && p.action && p.action.toolInput),
      saida: textoDe(p && p.observation),
    })),
  };
}

// ===== código deste nó =====
const a = $('[AGENT] Assistente Nautica').first().json;
const prep = $('[NORMALIZE] Preparar contexto').first().json;
const c = $('[GUARD] Avaliar conteúdo e custo').first().json.contexto;
const lead = $input.first().json || {};

const pp = posProcessar(a.output, {
  nome: lead.nome || c.lead_nome,
  email: lead.email || c.lead_email,
  ctasAnteriores: c.ctas_anteriores,
}, CONFIG);
const { tools, passos } = resumirPassos(a.intermediateSteps);
const consumo = estimarConsumo({
  sistemaChars: prep.sistema.length,
  historicoChars: c.historico_chars,
  textoChars: prep.texto.length,
  respostaChars: String(a.output || '').length,
  passos,
}, CONFIG);

return [{
  json: {
    resposta: pp.vazia ? respostaFixa('fallback', CONFIG) : pp.texto,
    fallback: pp.vazia,
    tools,
    cta_usada: pp.ctaUsada,
    resposta_cortada: pp.cortada,
    links_removidos: pp.linksRemovidos,
    pt_br: pp.ptBr.marcadores,
    tokens_entrada_est: consumo.tokensEntrada,
    tokens_saida_est: consumo.tokensSaida,
    custo_estimado_eur: consumo.custoEur,
    kb_hash: c.kb_hash,
    modelo: CONFIG.modelo.id,
  },
}];

